mapper.select:
SELECT id FROM exchange_rates
WHERE base_currency_id = #{baseCurrencyId}
  AND target_currency_id = #{targetCurrencyId}
  AND rate_date = #{rateDate}
LIMIT 1

SELECT deal_base_rate
FROM exchange_rates
WHERE target_currency_id = #{targetId}
  AND rate_date  <  #{currentDate}
ORDER BY rate_date DESC
LIMIT 1
